                case UnitConverterEnergyUnit.MegawattHour: return UnitConverterUnitSystem.Scientific;
                case UnitConverterEnergyUnit.GigawattHour: return UnitConverterUnitSystem.Scientific;
                case UnitConverterEnergyUnit.TerawattHour: return UnitConverterUnitSystem.Scientific;
                case UnitConverterEnergyUnit.WattDay: return UnitConverterUnitSystem.Scientific;
                case UnitConverterEnergyUnit.KilowattDay: return UnitConverterUnitSystem.Scientific;
                case UnitConverterEnergyUnit.MegawattDay: return UnitConverterUnitSystem.Scientific;
                case UnitConverterEnergyUnit.GigawattDay: return UnitConverterUnitSystem.Scientific;
                case UnitConverterEnergyUnit.TerawattDay: return UnitConverterUnitSystem.Scientific;
