                case UnitConverterEnergyUnit.DecathermUs: return UnitConverterUnitSystem.ImperialUS;
                case UnitConverterEnergyUnit.ThermImperial: return UnitConverterUnitSystem.ImperialUK;
                case UnitConverterEnergyUnit.DecathermImperial: return UnitConverterUnitSystem.ImperialUK;
                default: throw new ArgumentOutOfRangeException(nameof(unit), unit, "Unsupported Energy unit.");
            }
        }

        public static UnitConverterEnergyUnit[] GetUnitsForSystem(UnitConverterUnitSystem system)
        {
            var units = new List<UnitConverterEnergyUnit>();
            for (int i = 0; i < 48; i++) if (GetUnitSystem((UnitConverterEnergyUnit)i) == system) units.Add((UnitConverterEnergyUnit)i);
            return units.ToArray();
        }

        public static IReadOnlyList<UnitConverterUnitInfo> GetUnits() { return Metadata.Units; }
        public static UnitConverterUnitInfo GetUnitInfo(UnitConverterEnergyUnit unit) { Validate(unit); return Metadata.Units[(int)unit]; }
        public static string GetSymbol(UnitConverterEnergyUnit unit, IFormatProvider provider) { return GetUnitInfo(unit).GetSymbol(provider); }

        public static bool TryParseUnit(string text, out UnitConverterEnergyUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterEnergyUnit)id : default(UnitConverterEnergyUnit); return success;
        }

        public static UnitConverterEnergyUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterEnergyUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous Energy unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterEnergyValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterEnergyValue(value, (UnitConverterEnergyUnit)id) : default(UnitConverterEnergyValue); return success;
        }

        public static UnitConverterEnergyValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterEnergyValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous Energy unit.");
            return quantity;
        }

        public static string Format(double value, UnitConverterEnergyUnit unit, string format = "G", IFormatProvider provider = null)
        {
            return value.ToString(format, provider ?? CultureInfo.CurrentCulture) + " " + GetSymbol(unit, provider);
        }


